import { MeshBasicNodeMaterial, PlaneGeometry, Mesh } from 'three/webgpu';
import { color, vec3, mix, uv } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Color } = ctx.THREE;
  const mainGroup = new Group();

  const inkColor = config.intent?.visualSpec?.colors?.ink ?? '#16161d';
  const paperColor = config.intent?.visualSpec?.colors?.paper ?? '#e8ecf2';
  const accentColor = config.intent?.visualSpec?.colors?.accent ?? '#ff2a38';
  const surfaceColor = config.intent?.visualSpec?.colors?.surface ?? '#0b0b10';

  const width = 3.5;
  const height = 4.5;
  const geometry = new PlaneGeometry(width, height);

  const material = new MeshBasicNodeMaterial({
    transparent: true,
    depthWrite: false
  });

  const uMaxColor = color(new Color(surfaceColor));
  const uMinColor = color(new Color(inkColor));
  const gradient = mix(uMinColor, uMaxColor, uv().y);

  const accentColorNode = color(new Color(accentColor));
  const finalColor = mix(gradient, accentColorNode, mix(0.0, 0.04, uv().x));
  material.colorNode = finalColor;

  const cardMesh = new Mesh(geometry, material);
  mainGroup.add(cardMesh);

  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((texture) => {
      material.colorNode = vec3(texture.toVar());
      material.needsUpdate = true;
    }).catch((err) => {
      console.warn('Failed loading card texture image:', err);
    });
  }

  const borderGeo = new PlaneGeometry(width + 0.04, height + 0.04);
  const borderMat = new MeshBasicNodeMaterial({
    color: accentColor,
    transparent: true,
    opacity: 0.12,
    depthWrite: false
  });
  const borderMesh = new Mesh(borderGeo, borderMat);
  borderMesh.position.z = -0.01;
  mainGroup.add(borderMesh);

  mainGroup.position.set(0, 0, 0);

  mainGroup.userData = {
    handlers: {},
    cleanup: () => {
      geometry.dispose();
      material.dispose();
      borderGeo.dispose();
      borderMat.dispose();
    }
  };

  return mainGroup;
}
